225	  <script>
226	    (function () {
227	      const stored = localStorage.getItem('theme');
228	      if (stored === 'light' || stored === 'dark') {
229	        document.documentElement.dataset.theme = stored;
230	      }
231	    })();
232	  </script>
233	</head>
234	<body>
235	  <a class="skip-link" href="#main">Skip to content</a>
236	  <header>
237	    <nav aria-label="Primary">
238	      <ul>
239	        <li><a href="#home" data-nav-link aria-current="page">Home</a></li>
240	        <li><a href="#about" data-nav-link>About</a></li>
241	        <li><a href="#contact" data-nav-link>Contact</a></li>
242	      </ul>
243	      <button type="button" class="theme-toggle" id="theme-toggle" aria-label="Toggle color theme" aria-pressed="false"><span aria-hidden="true">🌙</span></button>
244	    </nav>
245	  </header>
246	  <main id="main" tabindex="-1">
247	    <section id="home" aria-labelledby="home-heading">
248	      <h1 id="home-heading">My Page</h1>
249	      <p>Welcome. This page is a starting point — replace this text with your own content.</p>
250	    </section>
251	
252	    <section id="about" aria-labelledby="about-heading">
253	      <h2 id="about-heading">About</h2>
254	      <p>Add a short description of what this page or project is about here.</p>
255	    </section>
256	
257	    <section id="contact" aria-labelledby="contact-heading">
258	      <h2 id="contact-heading">Contact</h2>
259	      <p>Reach out at <a href="mailto:hello@example.com">hello@example.com</a>.</p>
260	    </section>
261	  </main>
262	  <footer>
263	    <p>&copy; <span id="year">2026</span> My Page. All rights reserved.</p>
264	  </footer>
265	  <script>
266	    const yearEl = document.getElementById('year');
267	    if (yearEl) yearEl.textContent = String(new Date().getFullYear());
268	
269	    const themeToggle = document.getElementById('theme-toggle');
270	    const prefersDark = window.matchMedia('(prefers-color-scheme: dark)');
271	
272	    const currentTheme = () =>
273	      document.documentElement.dataset.theme || (prefersDark.matches ? 'dark' : 'light');
274	
275	    const updateToggleLabel = () => {
276	      const isDark = currentTheme() === 'dark';
277	      themeToggle.querySelector('span').textContent = isDark ? '☀️' : '🌙';
278	      themeToggle.setAttribute('aria-pressed', String(isDark));
279	      themeToggle.setAttribute('aria-label', isDark ? 'Switch to light theme' : 'Switch to dark theme');
280	    };
281	
282	    updateToggleLabel();
283	
284	    themeToggle.addEventListener('click', () => {
285	      const next = currentTheme() === 'dark' ? 'light' : 'dark';
286	      document.documentElement.dataset.theme = next;
287	      localStorage.setItem('theme', next);
288	      updateToggleLabel();
289	    });
290	
291	    prefersDark.addEventListener('change', () => {
292	      if (!document.documentElement.dataset.theme) updateToggleLabel();
293	    });
294	
295	    const navLinks = document.querySelectorAll('[data-nav-link]');
296	    const sections = [...navLinks]
297	      .map(link => document.querySelector(link.getAttribute('href')))
298	      .filter(Boolean);
299	
300	    const setActive = (id) => {
301	      navLinks.forEach(link => {
302	        if (link.getAttribute('href') === `#${id}`) {
303	          link.setAttribute('aria-current', 'page');
304	        } else {
305	          link.removeAttribute('aria-current');
306	        }
307	      });
308	    };
309	
310	    setActive(sections[0]?.id);
311	
312	    navLinks.forEach(link => {
313	      link.addEventListener('click', () => setActive(link.getAttribute('href').slice(1)));
314	    });
315	
316	    if ('IntersectionObserver' in window) {
317	      const observer = new IntersectionObserver((entries) => {
318	        const visible = entries
319	          .filter(entry => entry.isIntersecting)
320	          .sort((a, b) => b.intersectionRatio - a.intersectionRatio)[0];
321	        if (visible) setActive(visible.target.id);
322	      }, { rootMargin: '-40% 0px -50% 0px' });
323	      sections.forEach(section => section && observer.observe(section));
324	    }
325	  </script>
326	</body>
327	</html>
