const themeColorMetas = [
  document.getElementById('theme-color-light'),
  document.getElementById('theme-color-dark'),
].filter(Boolean);

const syncThemeColorMeta = () => {
  const color = currentTheme() === 'dark' ? '#111214' : '#ffffff';
  themeColorMetas.forEach(meta => meta.setAttribute('content', color));
};

syncThemeColorMeta();

themeToggle.addEventListener('click', () => {
  const next = currentTheme() === 'dark' ? 'light' : 'dark';
  document.documentElement.dataset.theme = next;
  try {
    localStorage.setItem('theme', next);
  } catch (e) {
    // localStorage may be unavailable; theme still applies for this session.
  }
  updateToggleLabel();
  syncThemeColorMeta();
});

